-- Run 258: execute no SQL Editor do Supabase, num projecto novo.
create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users on delete cascade, name text not null default 'Membro Run 258', bio text not null default '', avatar_url text, is_admin boolean not null default false, created_at timestamptz not null default now());
create table public.activities (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles on delete cascade, type text not null check(type in ('Corrida','Caminhada','Trail Run')), date date not null, distance numeric not null check(distance > 0), duration integer not null check(duration > 0), elevation integer not null default 0 check(elevation >= 0), notes text not null default '', photo_url text, source text not null default 'manual', external_id text, created_at timestamptz not null default now());
create table public.follows (follower_id uuid references public.profiles on delete cascade, following_id uuid references public.profiles on delete cascade, created_at timestamptz not null default now(), primary key(follower_id,following_id), check(follower_id <> following_id));
create table public.channels (id uuid primary key default gen_random_uuid(), name text unique not null, created_at timestamptz not null default now());
create table public.messages (id uuid primary key default gen_random_uuid(), channel_id uuid not null references public.channels on delete cascade, author_id uuid not null references public.profiles on delete cascade, body text not null default '', photo_url text, activity_id uuid references public.activities on delete set null, reply_to uuid references public.messages on delete set null, pinned boolean not null default false, created_at timestamptz not null default now());
create table public.reactions (message_id uuid references public.messages on delete cascade, user_id uuid references public.profiles on delete cascade, emoji text not null check(emoji in ('🔥','👏','💪')), primary key(message_id,user_id,emoji));
create table public.events (id uuid primary key default gen_random_uuid(), name text not null, event_date date not null, location text not null, meeting_time time not null, start_time time not null, description text not null default '', created_at timestamptz not null default now());
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select coalesce((select is_admin from profiles where id=auth.uid()),false) $$;
create function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into profiles(id,name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1))); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.new_profile();
alter table public.profiles enable row level security; alter table public.activities enable row level security; alter table public.follows enable row level security; alter table public.channels enable row level security; alter table public.messages enable row level security; alter table public.reactions enable row level security; alter table public.events enable row level security;
create policy profiles_read on public.profiles for select to authenticated using (true);
-- Users cannot change is_admin through the client; grant only editable columns.
revoke update on public.profiles from authenticated; grant update (name,bio,avatar_url) on public.profiles to authenticated;
create policy profiles_update on public.profiles for update to authenticated using (id=auth.uid()) with check (id=auth.uid());
create policy activities_read on public.activities for select to authenticated using (true);
create policy activities_insert on public.activities for insert to authenticated with check (user_id=auth.uid());
create policy activities_update on public.activities for update to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy activities_delete on public.activities for delete to authenticated using (user_id=auth.uid());
create policy follows_read on public.follows for select to authenticated using (true);
create policy follows_insert on public.follows for insert to authenticated with check (follower_id=auth.uid());
create policy follows_delete on public.follows for delete to authenticated using (follower_id=auth.uid());
create policy channels_read on public.channels for select to authenticated using (true);
create policy messages_read on public.messages for select to authenticated using (true);
create policy messages_insert on public.messages for insert to authenticated with check (author_id=auth.uid() and pinned=false);
create policy messages_delete on public.messages for delete to authenticated using (author_id=auth.uid() or public.is_admin());
create policy messages_admin_update on public.messages for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy reactions_read on public.reactions for select to authenticated using (true);
create policy reactions_insert on public.reactions for insert to authenticated with check (user_id=auth.uid());
create policy reactions_delete on public.reactions for delete to authenticated using (user_id=auth.uid());
create policy events_read on public.events for select to anon,authenticated using (true);
create policy events_admin on public.events for all to authenticated using (public.is_admin()) with check (public.is_admin());
insert into storage.buckets(id,name,public) values ('photos','photos',false) on conflict do nothing;
create policy photos_read on storage.objects for select to authenticated using (bucket_id='photos');
create policy photos_insert on storage.objects for insert to authenticated with check (bucket_id='photos' and (storage.foldername(name))[1]=auth.uid()::text);
create policy photos_delete on storage.objects for delete to authenticated using (bucket_id='photos' and (storage.foldername(name))[1]=auth.uid()::text);
alter publication supabase_realtime add table public.messages, public.reactions;
